const details = await browserjs(tabId, () => {
  const brand = document.querySelector('[itemprop="brand"]')?.textContent?.trim();
  const name = document.querySelector('[itemprop="name"]')?.textContent?.trim();
  const price = document.querySelector('[data-test-id="product-price"], [class*="price"]')?.textContent?.trim();
  const desc = document.querySelector('[itemprop="description"]')?.textContent?.trim();

  // Find measurements
  const lis = Array.from(document.querySelectorAll('ul li')).map(li => li.textContent.trim());
  const measurements = lis.filter(li => 
    li.toLowerCase().includes('heel') || 
    li.toLowerCase().includes('shaft') || 
    li.toLowerCase().includes('circumference') || 
    li.toLowerCase().includes('weight')
  );

  // Check size 5.5
  const sizeButtons = Array.from(document.querySelectorAll('button, input[type=radio]')).filter(el => {
    return el.textContent?.trim() === '5.5' || el.getAttribute('aria-label')?.includes('5.5') || el.value === '5.5';
  }).map(el => ({
    text: el.textContent?.trim(),
    ariaLabel: el.getAttribute('aria-label'),
    disabled: el.disabled || el.getAttribute('aria-disabled') === 'true' || el.classList.contains('disabled')
  }));

  return { brand, name, price, measurements, desc: desc?.slice(0, 500), sizeButtons, allLis: lis.slice(0, 15) };
});

