const tabId = 725789690;

const candidateUrls = [
  "https://www.zappos.com/p/anne-klein-wei-black/product/9918858/color/3",
  "https://www.zappos.com/p/blondo-natasia-waterproof-black-leather/product/9987989/color/72",
  "https://www.zappos.com/p/blondo-cassidie-waterproof-black/product/10017288/color/3",
  "https://www.zappos.com/p/david-tate-dahana-black-lambskin/product/9899225/color/54858",
  "https://www.zappos.com/p/sam-edelman-taylin-black-suede/product/10034333/color/106",
  "https://www.zappos.com/p/eric-michael-juliana-black-2/product/8753244/color/60041"
];

const results = [];
for (const url of candidateUrls) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 8000 });
  const data = await browserjs(tabId, () => {
    const brand = document.querySelector('[itemprop="brand"]')?.textContent?.trim();
    const name = document.querySelector('[itemprop="name"]')?.textContent?.trim();
    const price = document.querySelector('[data-test-id="product-price"], [class*="price"]')?.textContent?.trim();
    const desc = document.querySelector('[itemprop="description"]')?.textContent?.trim();
    const lis = Array.from(document.querySelectorAll('ul li')).map(li => li.textContent.trim());
    const meas = lis.filter(l => l.includes('Height') || l.includes('Circumference') || l.includes('Shaft') || l.includes('Heel'));

    // Check size 5.5
    const size55Btn = Array.from(document.querySelectorAll('button, input[type=radio]')).find(el => {
      return el.textContent?.trim() === '5.5' || el.getAttribute('aria-label')?.includes('5.5') || el.value === '5.5';
    });
    const size55Avail = size55Btn ? !(size55Btn.disabled || size55Btn.getAttribute('aria-disabled') === 'true') : false;

    return { brand, name, price, meas, desc: desc?.slice(0, 300), size55Avail, lis: lis.slice(7, 16) };
  });
  results.push({ url, ...data });
}

console.log(JSON.stringify(results, null, 2));

