const prods = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a[href*="/dp/"]'));
  const map = new Map();
  links.forEach(l => {
    const text = l.textContent.replace(/\s+/g, ' ').trim();
    const href = l.href.split('?')[0];
    if (text.length > 15 && !map.has(href)) {
      map.set(href, text);
    }
  });
  return Array.from(map.entries()).map(([href, title]) => ({ href, title }));
});
