const tabId = 725789690;

const testList = [
  "https://www.amazon.com/Modatope-Black-Knee-Chunky-Boots/dp/B0CB7LSW5H/",
  "https://www.amazon.com/Cozivwaiy-Womens-Stretch-Leather-Comfortable/dp/B0FJCVJ9B5/",
  "https://www.amazon.com/Coutgo-Womens-Pointed-Zipper-Winter/dp/B0FG6QT5N3/"
];

const results = [];
for (const url of testList) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 8000 });
  const data = await browserjs(tabId, () => {
    const title = document.querySelector('h1#title')?.textContent?.trim() || document.querySelector('#productTitle')?.textContent?.trim();
    const price = document.querySelector('.a-price .a-offscreen')?.textContent?.trim() || document.querySelector('#corePrice_feature_div .a-offscreen')?.textContent?.trim();
    const desc = document.querySelector('#productDescription')?.textContent?.trim();
    const bullets = Array.from(document.querySelectorAll('#feature-bullets li')).map(li => li.textContent.replace(/\s+/g, ' ').trim()).filter(t => t.length > 5);

    // check size 5.5
    const sizeSelect = document.getElementById('native_dropdown_selected_size_name');
    let has55 = false;
    let sizeText = "";
    if (sizeSelect) {
      const opt = Array.from(sizeSelect.options).find(o => o.text.includes('5.5'));
      if (opt) {
        has55 = !opt.disabled;
        sizeText = opt.text;
      }
    } else {
      const sizeBtns = Array.from(document.querySelectorAll('[id^="size_name_"], button')).filter(b => b.textContent.trim() === '5.5');
      if (sizeBtns.length > 0) {
        has55 = !sizeBtns[0].classList.contains('swatchUnavailable');
        sizeText = "5.5";
      }
    }

    return { title, price, has55, sizeText, bullets: bullets.slice(0, 4), desc: desc?.slice(0, 300) };
  });
  results.push({ url, ...data });
}

console.log(JSON.stringify(results, null, 2));

