const tabId = 725789690;

const candidateUrls = [
  "https://www.zappos.com/p/vince-camuto-pamlia-knee-high-boots-black/product/10070972/color/3",
  "https://www.zappos.com/p/naturalizer-27-edit-brooke-knee-high-boots-black-leather/product/10082761/color/72",
  "https://www.nordstrom.com/s/barile-knee-high-boot-women/8426356",
  "https://www.nordstrom.com/s/aerosoles-prue-tall-boot-women/8668730"
];

const results = [];
for (const url of candidateUrls) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 8000 });
  const data = await browserjs(tabId, () => {
    const isNord = window.location.hostname.includes('nordstrom');
    const brand = isNord ? document.querySelector('h1')?.parentElement?.querySelector('span, a')?.textContent?.trim() : document.querySelector('[itemprop="brand"]')?.textContent?.trim();
    const name = document.querySelector('h1')?.textContent?.trim();
    const price = document.querySelector('[data-test-id="product-price"], [class*="price"], [data-element="product-price"]')?.textContent?.trim();
    const lis = Array.from(document.querySelectorAll('ul li')).map(li => li.textContent.trim());
    const meas = lis.filter(l => l.includes('Height') || l.includes('Circumference') || l.includes('Shaft') || l.includes('Heel') || l.includes('Weight'));

    // Check size 5.5
    const sizeBtns = Array.from(document.querySelectorAll('button, input[type=radio]')).filter(el => {
      const t = el.textContent?.trim();
      return t === '5.5' || t === '5 1/2' || el.getAttribute('aria-label')?.includes('5.5');
    });
    const size55Avail = sizeBtns.length > 0 ? !(sizeBtns[0].disabled || sizeBtns[0].getAttribute('aria-disabled') === 'true' || sizeBtns[0].classList.contains('unavailable')) : false;

    return { isNord, brand, name, price, meas, size55Avail, lis: lis.slice(7, 18) };
  });
  results.push({ url, ...data });
}

console.log(JSON.stringify(results, null, 2));

